var T0=Date.now();/*Signature edition*/
var C=5,RC=20,P=0.9;
var passed=0;
for(var r=0;r<RC;r++){var ok=true;for(var c=0;c<C;c++)if(R()>P){ok=false;break;}if(ok)passed++;}
console.log(JSON.stringify({id:"JAH-APX60S-000001",ok:true,metrics:{checks:C,candidates:RC,passed:passed,blocked:RC-passed,pass_rate:+(passed/RC).toFixed(3)},ms:Date.now()-T0}));

